from fastapi import FastAPI
import json

app = FastAPI(
    title="Test App",
    version="1.0.0",
    external_docs={"description": "External Docs", "url": "https://example.com"}
)

def test_external_docs():
    schema = app.openapi()
    assert schema["info"]["externalDocs"] == {"description": "External Docs", "url": "https://example.com"}
    print("Test passed!")

if __name__ == "__main__":
    try:
        test_external_docs()
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
    except Exception as e:
        print(f"An error occurred: {e}")
        exit(1)
